import{_ as t,o as i,c as a,ao as s}from"./chunks/framework.CXYRQASs.js";const k=JSON.parse('{"title":"Geometry and meshes","description":"","frontmatter":{},"headers":[],"relativePath":"manual/geometry.md","filePath":"manual/geometry.md","lastUpdated":null}'),o={name:"manual/geometry.md"};function l(r,e,n,p,d,h){return i(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="Geometry-and-meshes" tabindex="-1">Geometry and meshes <a class="header-anchor" href="#Geometry-and-meshes" aria-label="Permalink to &quot;Geometry and meshes {#Geometry-and-meshes}&quot;">​</a></h1><p>A simulation starts from a geometry recipe (a &quot;setup&quot;), which <a href="/SpinDoctor.jl/dev/api#SpinDoctor.create_geometry"><code>create_geometry</code></a> turns into a finite element mesh in three steps:</p><ol><li><p>a configuration of cells (positions and radii), random by default (<code>SpinDoctor.create_cells</code>);</p></li><li><p>the surfaces of the cells and of the extracellular space (ECS) (<code>SpinDoctor.create_surfaces</code>);</p></li><li><p>a mesh of triangles (2D, with Triangle) or tetrahedra (3D, with TetGen), split into compartments (<code>SpinDoctor.create_mesh</code>, <code>SpinDoctor.split_mesh</code>).</p></li></ol><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">setup </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> CylinderSetup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(; ncell </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, layersizes </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.6</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], ecs </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> BoxECS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(; margin </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mesh, surfaces, cells </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> create_geometry</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(setup; rng </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Xoshiro</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span></code></pre></div><p>See <a href="/SpinDoctor.jl/dev/examples/generated/geometries#geometries">Geometry recipes</a> for pictures of all of them.</p><h2 id="Recipes" tabindex="-1">Recipes <a class="header-anchor" href="#Recipes" aria-label="Permalink to &quot;Recipes {#Recipes}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Recipe</th><th style="text-align:center;">Dimension</th><th style="text-align:left;">Cells</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/SpinDoctor.jl/dev/api#SpinDoctor.PlateSetup"><code>PlateSetup</code></a></td><td style="text-align:center;">2D</td><td style="text-align:left;">stacked plates</td></tr><tr><td style="text-align:left;"><a href="/SpinDoctor.jl/dev/api#SpinDoctor.SlabSetup"><code>SlabSetup</code></a></td><td style="text-align:center;">3D</td><td style="text-align:left;">stacked slabs (extruded plates)</td></tr><tr><td style="text-align:left;"><a href="/SpinDoctor.jl/dev/api#SpinDoctor.DiskSetup"><code>DiskSetup</code></a></td><td style="text-align:center;">2D</td><td style="text-align:left;">disks, with layers</td></tr><tr><td style="text-align:left;"><a href="/SpinDoctor.jl/dev/api#SpinDoctor.CylinderSetup"><code>CylinderSetup</code></a></td><td style="text-align:center;">3D</td><td style="text-align:left;">cylinders (extruded disks), with layers</td></tr><tr><td style="text-align:left;"><a href="/SpinDoctor.jl/dev/api#SpinDoctor.SphereSetup"><code>SphereSetup</code></a></td><td style="text-align:center;">3D</td><td style="text-align:left;">spheres, with layers</td></tr><tr><td style="text-align:left;"><a href="/SpinDoctor.jl/dev/api#SpinDoctor.VoronoiSetup"><code>VoronoiSetup</code></a></td><td style="text-align:center;">3D</td><td style="text-align:left;">polyhedral cells filling a periodic box</td></tr><tr><td style="text-align:left;"><a href="/SpinDoctor.jl/dev/api#SpinDoctor.NeuronSetup"><code>NeuronSetup</code></a></td><td style="text-align:center;">3D</td><td style="text-align:left;">a neuron from a volume mesh (Gmsh format)</td></tr></tbody></table><p>Disks, cylinders and spheres may have several layers (<code>layersizes</code>, relative radii), for example an axon in a myelin sheath, or a nucleus in a cell. Extruded setups (slabs and cylinders) may be bent and twisted (<a href="/SpinDoctor.jl/dev/api#SpinDoctor.ExtrusionSetup"><code>ExtrusionSetup</code></a>).</p><h2 id="Extracellular-space" tabindex="-1">Extracellular space <a class="header-anchor" href="#Extracellular-space" aria-label="Permalink to &quot;Extracellular space {#Extracellular-space}&quot;">​</a></h2><p>The cells of disks, cylinders, spheres and neurons may be immersed in an ECS:</p><ul><li><p><a href="/SpinDoctor.jl/dev/api#SpinDoctor.NoECS"><code>NoECS</code></a>: no ECS;</p></li><li><p><a href="/SpinDoctor.jl/dev/api#SpinDoctor.BoxECS"><code>BoxECS</code></a>: a box around the cells, with a margin;</p></li><li><p><a href="/SpinDoctor.jl/dev/api#SpinDoctor.ConvexHullECS"><code>ConvexHullECS</code></a>: the convex hull of the cells, with a margin;</p></li><li><p><a href="/SpinDoctor.jl/dev/api#SpinDoctor.PeriodicBoxECS"><code>PeriodicBoxECS</code></a>: a sample of periodic tissue (disks and cylinders).</p></li></ul><h2 id="Samples-of-periodic-tissue" tabindex="-1">Samples of periodic tissue <a class="header-anchor" href="#Samples-of-periodic-tissue" aria-label="Permalink to &quot;Samples of periodic tissue {#Samples-of-periodic-tissue}&quot;">​</a></h2><p>For dense tissue, <a href="/SpinDoctor.jl/dev/api#SpinDoctor.PeriodicBoxECS"><code>PeriodicBoxECS</code></a> and <a href="/SpinDoctor.jl/dev/api#SpinDoctor.VoronoiSetup"><code>VoronoiSetup</code></a> fill a box with cells, cut by its faces, with their periodic images entering on the opposite faces:</p><ul><li><p><a href="/SpinDoctor.jl/dev/api#SpinDoctor.periodic_packing"><code>periodic_packing</code></a> packs disks or spheres with gaps between them, up to about 80 % of the area or 60 % of the volume (counting the gaps);</p></li><li><p><a href="/SpinDoctor.jl/dev/api#SpinDoctor.VoronoiSetup"><code>VoronoiSetup</code></a> creates polyhedral cells for any volume fraction.</p></li></ul><p>The meshes are periodic (the opposite faces of the box have the same points), so that the solvers can use periodic boundary conditions (see <a href="/SpinDoctor.jl/dev/manual/solvers#solvers">Solvers</a>). Then the sample represents a larger piece of tissue, without walls.</p><h2 id="Cell-configurations" tabindex="-1">Cell configurations <a class="header-anchor" href="#Cell-configurations" aria-label="Permalink to &quot;Cell configurations {#Cell-configurations}&quot;">​</a></h2><p>The cell configuration <code>cells</code> returned by <a href="/SpinDoctor.jl/dev/api#SpinDoctor.create_geometry"><code>create_geometry</code></a> may be given back to create the same cells with other parameters (e.g. a finer mesh), or replaced by a configuration of your own, for example from another packing algorithm:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mesh, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> create_geometry</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(setup; cells)</span></span></code></pre></div><p>The random configurations are drawn from the random number generator <code>rng</code>.</p><h2 id="Compartments-and-boundaries" tabindex="-1">Compartments and boundaries <a class="header-anchor" href="#Compartments-and-boundaries" aria-label="Permalink to &quot;Compartments and boundaries {#Compartments-and-boundaries}&quot;">​</a></h2><p>The mesh is split into compartments, numbered as follows:</p><ul><li><p>plates and slabs: one per plate;</p></li><li><p>disks, cylinders and spheres: the inner layers of all the cells, then the next layers, ..., then the ECS (e.g. with two layers and three cells: the axons 1-3, the myelin 4-6, the ECS 7);</p></li><li><p>neurons: the neuron, then the ECS.</p></li></ul><p>The boundaries are the interfaces between pairs of compartments, followed by the outer boundaries of each compartment. The coefficients of the recipes (<a href="/SpinDoctor.jl/dev/api#SpinDoctor.coefficients"><code>coefficients</code></a>) follow this numbering. <a href="/SpinDoctor.jl/dev/api#SpinDoctor.compartment_mesh"><code>compartment_mesh</code></a> extracts one compartment as a mesh of its own, and <a href="/SpinDoctor.jl/dev/api#SpinDoctor.box_faces"><code>box_faces</code></a> finds the facets of a box-shaped compartment on each face.</p><h2 id="Files" tabindex="-1">Files <a class="header-anchor" href="#Files" aria-label="Permalink to &quot;Files {#Files}&quot;">​</a></h2><p>By default, <a href="/SpinDoctor.jl/dev/api#SpinDoctor.create_geometry"><code>create_geometry</code></a> writes no files. With <code>using JLD2</code>, the geometry can be stored in a file and loaded again when it was created for the same setup:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> JLD2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mesh, surfaces, cells </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> create_geometry</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(setup; cache </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;geometry.jld2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>With <code>savedir</code>, the geometry is written as text files in the TetGen format of the MATLAB version of SpinDoctor.</p>`,27)])])}const u=t(o,[["render",l]]);export{k as __pageData,u as default};
